CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PERSONACLEAVER" ("IDPERSONAL", "INTERPRETACION", "INTERPRETACION1", "INTERPRETACION2", "NOMBRE", "NOMBRE1", "NOMBRE2") AS 
  SELECT PersonalInterpretacion.IdPersonal, Interpretacion.Interpretacion, Interpretacion_1.Interpretacion as Interpretacion1, Interpretacion_2.Interpretacion as Interpretacion2, Interpretacion.Nombre, Interpretacion_1.Nombre as Nombre1, Interpretacion_2.Nombre as Nombre2 FROM ((PersonalInterpretacion LEFT JOIN Interpretacion ON PersonalInterpretacion.IdInterpretacion1 = Interpretacion.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_1 ON PersonalInterpretacion.IdInterpretacion2 = Interpretacion_1.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_2 ON PersonalInterpretacion.IdInterpretacion3 = Interpretacion_2.IdInterpretacion WHERE (((PersonalInterpretacion.IdPrueba)=7));
